          rawErrors: [`Simulation timed out after ${Math.round(timeoutMs / 1000)}s`],
          rawInfo: '',
        });
        setError({
          message: 'The spirits went silent (timeout)',
          rawErrors: [`Simulation timed out after ${Math.round(timeoutMs / 1000)}s`],
          rawInfo: '',
        });
        setState('error');

        // Recreate worker on timeout
        createWorker();
        isProcessingRef.current = false;
        processQueue();
      }
    }, timeoutMs);

