 */
function summariseTransient(result: SimResult): CompactSummary {
  if (!result.data || result.data.length === 0) {
    return {
      analysisType: 'transient',
      analysisTime: undefined,
      minValue: undefined,
      maxValue: undefined,
      finalValue: undefined,
      riseTime: undefined,
      tau: undefined,
      overshoot: false,
      peak: undefined,
      notes: 'No data returned',
    };
  }

