  const overshoot = detectOvershoot(voltageValues);

  return {
    analysisType: 'transient',
    analysisTime: timeValues[timeValues.length - 1],
    minValue: minVal,
    maxValue: maxVal,
    finalValue: finalVal,
    riseTime,
    tau,
    overshoot,
    notes: overshoot ? 'Ringing detected' : undefined,
