  if (magnitudeDb.length < 2) {
    return null;
  }

  const maxGain = Math.max(...magnitudeDb);
  const target = maxGain - 3;

  // Find first crossing below max – 3 dB
  for (let i = 0; i < magnitudeDb.length - 1; i++) {
    if (magnitudeDb[i] >= target && magnitudeDb[i + 1] < target) {
      return i;
    }
  }

  return null;
}

/**
