/**
 * Trim summary to stay under token budget
 */
export function trimSummary(summary: CompactSummary): CompactSummary {
  const json = JSON.stringify(summary);
  if (json.length <= 2000) {
    return summary;
  }

  // Trim decimal places progressively
  const trimmed = { ...summary };
  let decimals = 6;

  while (JSON.stringify(trimmed).length > 2000 && decimals > 0) {
    decimals--;
    // Recursively trim all numbers
    Object.keys(trimmed).forEach((key) => {
      const val = (trimmed as Record<string, unknown>)[key];
      if (typeof val === 'number') {
        (trimmed as Record<string, unknown>)[key] = parseFloat(val.toFixed(decimals));
      }
    });
  }

  return trimmed;
}

