    const trimNumeric = (obj: Record<string, unknown>): void => {
      Object.keys(obj).forEach((key) => {
        const val = obj[key];
        if (typeof val === 'number' && !Number.isInteger(val)) {
          obj[key] = decimals >= 0 ? parseFloat(val.toFixed(decimals)) : Math.round(val);
