          trimNumeric(val as Record<string, unknown>);
        }
      });
    };

    trimNumeric(trimmed as Record<string, unknown>);
  }

  // If still too long, remove optional fields
  if (JSON.stringify(trimmed).length > 2000) {
    if (trimmed.notes) {
      trimmed.notes = trimmed.notes.slice(0, 50) + '...';
    }
