    };
  }

  const xData = result.data[0];
  const xValues = extractRealValues(xData.values);
  const yData = result.data[1];
  const yValues = extractRealValues(yData.values);

  const yMin = Math.min(...yValues);
  const yMax = Math.max(...yValues);

