  return {
    analysisType: 'dc',
    minValue: yMin,
    maxValue: yMax,
    notes: `DC sweep range: ${yMin.toFixed(3)} to ${yMax.toFixed(3)}`,
  };
}

/**
 * Summarise operating point (.op)
 */
function summariseOp(result: SimResult): CompactSummary {
  const summary: CompactSummary = {
