    analysisTime: timeValues[timeValues.length - 1],
    minValue: minVal,
    maxValue: maxVal,
    finalValue: finalVal,
    riseTime: riseTime !== null ? riseTime : undefined,
    tau: tau !== null ? tau : undefined,
    overshoot,
    notes: overshoot ? 'Ringing detected' : undefined,
  };
}

/**
