  refdes?: string;
  nodes?: string[];
  value?: string;
  model?: string;
  // For directives
  directiveType?: AnalysisType | 'model' | 'subckt' | 'ends' | 'end' | 'save' | 'print' | 'probe';
  directiveParams?: string;
}

export interface ParsedNetlist {
  title: string | null;
  lines: ParsedLine[];
  components: Array<{
    refdes: string;
    nodes: string[];
    value: string;
    model?: string;
    lineNumber: number;
